mapper.select:
SELECT A.ORDER_NO AS orderNo , B.ORDER_SEQ AS orderSeq , A.TOTAL_PRICE AS totalPrice , DATE_FORMAT(A.ORDER_DATE, '%Y-%m-%d') AS orderDate , A.ORDER_PERSON_NM AS orderPersonNm , A.ORDER_TELNO AS orderTelno , A.ORDER_TELNO_1 AS orderTelno1 , A.ORDER_TELNO_2 AS orderTelno2 , A.ORDER_TELNO_3 AS orderTelno3 , A.SEND_PERSON_NM AS sendPersonNm , A.SEND_TELNO AS sendTelno , A.SEND_TELNO_1 AS sendTelno1 , A.SEND_TELNO_2 AS sendTelno2 , A.SEND_TELNO_3 AS sendTelno3 , A.SEND_ZIP_NO sendZipNo , A.SEND_ADDRESS_MAIN sendAddressMain , A.SEND_ADDRESS_DETAIL sendAddressDetail , A.RECEIVE_PERSON_NM AS receivePersonNm , A.RECEIVE_TELNO AS receiveTelno , A.RECEIVE_TELNO_1 AS receiveTelno1 , A.RECEIVE_TELNO_2 AS receiveTelno2 , A.RECEIVE_TELNO_3 AS receiveTelno3 , A.RECEIVE_ZIP_NO receiveZipNo , A.RECEIVE_ADDRESS_MAIN receiveAddressMain , A.RECEIVE_ADDRESS_DETAIL receiveAddressDetail , A.ORDER_REMARKS AS orderRemarks , A.DEPOSIT_PERSON_NM AS depositPersonNm , A.DEPOSIT_REMARKS AS depositRemarks , DATE_FORMAT(A.DEPOSIT_CONFIRM_DATE, '%Y-%m-%d %H:%i:%s') AS depositConfirmDate , DATE_FORMAT(B.DLVR_CONFIRM_DATE, '%Y-%m-%d') AS dlvrConfirmDate , DATE_FORMAT(A.CANCEL_DATE, '%Y-%m-%d') AS cancelDate , A.BASIC_FARES AS basicFares , A.BOX_TYPE AS boxType , A.FARE_TYPE AS fareType , B.QTY AS qty , A.SELLER_NO AS sellerNo , C.ITEM_NO AS itemNo , C.KEEPING_METHOD AS keepingMethod , D.OPTION_NO AS optionNo , D.OPTION_NM AS optionNm , D.ITEM_PRICE AS itemPrice , D.SHIPPING_FEE AS shippingFee , C.ITEM_NM AS itemNm , C.IMAGE_PATH_1 AS imagePath1 , (SELECT COUNT(INVOICE_NO) FROM INVOICE WHERE ORDER_NO = A.ORDER_NO) AS invoiceCnt FROM ORDER_LIST_MAIN A, ORDER_LIST_DETAIL B, ITEMS C, ITEM_OPTION D, USERS E WHERE 1=1 AND A.ORDER_NO = B.ORDER_NO AND B.ITEM_NO = C.ITEM_NO AND B.OPTION_NO = D.OPTION_NO AND A.USER_NO = E.USER_NO AND A.ORDER_NO = ${orderNo}
AND (A.USER_NO = #{userNo} or A.RECEIVE_TELNO = (SELECT TELNO FROM USERS WHERE USER_NO = #{userNo}))
ORDER BY A.ORDER_NO DESC

mapper.update:
UPDATE ORDER_LIST_MAIN
   SET DEPOSIT_CONFIRM_DATE = CURRENT_TIMESTAMP
 WHERE ORDER_NO = ${orderNo}

UPDATE ORDER_LIST_DETAIL
   SET DLVR_CONFIRM_DATE = CURRENT_TIMESTAMP
 WHERE ORDER_NO = ${orderNo}
   AND ORDER_SEQ = ${orderSeq}

UPDATE ORDER_LIST_DETAIL
   SET INVOICE_NO = #{invoiceNo}
 WHERE ORDER_NO = ${orderNo}
   AND ORDER_SEQ = ${orderSeq}

mapper.insert:
INSERT INTO INVOICE
(
  ORDER_NO
, INVOICE_NO
) VALUES (
  ${orderNo}
, ${invoiceNo}
)

mapper.delete:
DELETE FROM INVOICE
 WHERE ORDER_NO = ${orderNo}
   AND INVOICE_NO = ${invoiceNo}

mapper.select:
SELECT ORDER_NO AS orderNo
      , INVOICE_NO AS invoiceNo
  FROM INVOICE
 WHERE ORDER_NO = ${orderNo}


   AND ORDER_NO IN (
       SELECT ORDER_NO FROM ORDER_LIST_MAIN
        WHERE USER_NO = #{userNo} OR RECEIVE_TELNO = #{telno}
   )

mapper.update:
UPDATE ORDER_LIST_MAIN
   SET BASIC_FARES = #{basicFares}
      , BOX_TYPE = #{boxType}
      , FARE_TYPE = #{fareType}
 WHERE ORDER_NO = ${orderNo}
